-- Fix identity sequences for all tables that use "generated by default as identity"
-- This resets each sequence to MAX(id) + 1, preventing duplicate key violations
-- when inserts rely on the auto-generated identity value.

-- Vendors
SELECT setval(
  pg_get_serial_sequence('public.vendors', 'id'),
  COALESCE((SELECT MAX(id) FROM public.vendors), 0) + 1,
  false
);

